//0x8F08
Text_8EE8:
.stringn "\x05FL|JANAFF||\x0701\x081Dわ、\x02w1わかった。\x02w4わかったから\x02mc！\x02md\x02w5\n"
.stringn "そんな真剣になるなよ。\x02w4\n"
.stringn "\x02mc………\x02md\x02w3\x02ec照れる。\x02w2\x11"
db 0
.align 4
